export function getDistrictsForProvince(provinceSlug: string): District[] {
  return districts.filter((d) => d.provinceSlug === provinceSlug);
}

export function getDistrictBySlug(
  provinceSlug: string,
  districtSlug: string,
): District | undefined {
  return districts.find(
    (d) => d.provinceSlug === provinceSlug && d.slug === districtSlug,
  );
}

/** District names grouped by province slug — derived from `districts`. */
export const districtNamesByProvince: Record<string, string[]> = (() => {
  const map: Record<string, string[]> = {};
  for (const d of districts) {
    (map[d.provinceSlug] ??= []).push(d.name);
  }
  return map;
})();

export function getNeighborDistricts(district: District): District[] {
  return (district.neighbors ?? [])
    .map((slug) => getDistrictBySlug(district.provinceSlug, slug))
    .filter((d): d is District => Boolean(d));
}
